CREATE OR REPLACE FUNCTION private.emit_member_sync_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_entity_id uuid;
  v_change text;
begin
  v_change:=lower(tg_op);

  if tg_op='DELETE' then
    v_contact_id:=old.contact_id;
    v_entity_id:=old.id;
  else
    v_contact_id:=new.contact_id;
    v_entity_id:=new.id;
  end if;

  if v_contact_id is null then
    return coalesce(new,old);
  end if;

  select hm.household_id
    into v_household_id
  from public.household_members hm
  where hm.contact_id=v_contact_id
    and hm.status='active'
  order by hm.is_primary desc,hm.created_at
  limit 1;

  insert into public.member_sync_events(
    contact_id,household_id,entity_type,entity_id,change_type,metadata
  )
  values(
    v_contact_id,
    v_household_id,
    tg_argv[0],
    v_entity_id,
    v_change,
    jsonb_build_object('table',tg_table_name)
  );

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION private.process_submitted_client_checkin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_coach uuid;
  v_value numeric;
  v_key text;
begin
  if NEW.status <> 'submitted'
     or (TG_OP='UPDATE' and OLD.status is not distinct from NEW.status) then
    return NEW;
  end if;

  foreach v_key in array array['energy','mood','stress','sleep_hours']
  loop
    begin
      v_value := nullif(NEW.responses->>v_key,'')::numeric;
    exception when others then
      v_value := null;
    end;

    if v_value is not null then
      insert into public.progress_entries(
        contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
      )
      values(
        NEW.contact_id,NEW.membership_id,v_key,v_value,coalesce(NEW.submitted_at,now()),
        'member',NEW.created_by,jsonb_build_object('checkin_id',NEW.id)
      );
    end if;
  end loop;

  select coach_user_id into v_coach
  from public.client_coach_assignments
  where contact_id=NEW.contact_id
    and role='primary'
    and status='active'
  limit 1;

  insert into public.follow_up_tasks(
    contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
  )
  select
    NEW.contact_id,v_coach,'Review client weekly check-in',
    now()+interval '1 day','open','normal','review',
    'Review the client’s submitted weekly check-in, note wins/challenges/questions, and determine whether a personal response or coaching adjustment is needed.'
  where not exists (
    select 1 from public.follow_up_tasks
    where contact_id=NEW.contact_id
      and title='Review client weekly check-in'
      and status='open'
  );

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    NEW.contact_id,'weekly_checkin_submitted','Weekly ReVitalized check-in submitted',
    null,NEW.created_by,jsonb_build_object('checkin_id',NEW.id)
  );

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_household_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_household_id uuid;
  v_membership_id uuid;
begin
  if TG_TABLE_NAME='client_access' then
    if NEW.status='active' and NEW.user_id is not null and NEW.household_id is not null then
      perform private.ensure_household_conversation(
        NEW.household_id,NEW.membership_id,NEW.user_id
      );
    end if;
    return NEW;
  end if;

  if TG_TABLE_NAME='household_members' then
    v_household_id := coalesce(NEW.household_id,OLD.household_id);

    select ca.membership_id into v_membership_id
    from public.client_access ca
    where ca.household_id=v_household_id
      and ca.membership_id is not null
    order by ca.created_at
    limit 1;

    perform private.ensure_household_conversation(
      v_household_id,v_membership_id,(select auth.uid())
    );
    return coalesce(NEW,OLD);
  end if;

  return coalesce(NEW,OLD);
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_active_household_after_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_id uuid;
begin
  v_id := coalesce(NEW.household_id,OLD.household_id);
  perform private.assert_household_composition(v_id);
  return coalesce(NEW,OLD);
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_household_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_type text;
begin
  select household_type into v_type
  from public.households
  where id=NEW.household_id;

  if v_type is null then
    raise exception 'Household not found';
  end if;

  if NEW.relationship_type='husband' and NEW.sex is distinct from 'male' then
    raise exception 'A husband must be recorded as male';
  end if;

  if NEW.relationship_type='wife' and NEW.sex is distinct from 'female' then
    raise exception 'A wife must be recorded as female';
  end if;

  if v_type='individual' and NEW.relationship_type <> 'self' then
    raise exception 'Individual households can contain only the individual';
  end if;

  if v_type='couple' and NEW.relationship_type not in ('husband','wife') then
    raise exception 'Couple households are husband and wife only';
  end if;

  if v_type='family' and NEW.relationship_type not in ('husband','wife','child','dependent') then
    raise exception 'Family households are husband, wife, children and dependents only';
  end if;

  return NEW;
end;
$function$
